<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Parent/Guardian');$q=db()->prepare('SELECT s.id,u.name,s.enrollment_no FROM parent_students ps JOIN parents p ON p.id=ps.parent_id JOIN students s ON s.id=ps.student_id JOIN users u ON u.id=s.user_id WHERE p.user_id=?');$q->execute([actor_id()]);$kids=$q->fetchAll();page_top('Child Results');foreach($kids as $k){$m=db()->prepare('SELECT sub.code,sub.name,m.total_marks,m.grade,m.grade_point,m.result FROM marks m JOIN subjects sub ON sub.id=m.subject_id WHERE m.student_id=? ORDER BY m.id DESC');$m->execute([$k['id']]);?><div class='card p-3 mb-3'><h5><?=e($k['name'])?></h5><table class='table'><tr><th>Subject</th><th>Total</th><th>Grade</th><th>Result</th></tr><?php foreach($m as $r):?><tr><td><?=e($r['code'].' · '.$r['name'])?></td><td><?=e($r['total_marks'])?></td><td><?=e($r['grade'])?></td><td><?=e($r['result'])?></td></tr><?php endforeach;?></table></div><?php }page_bottom();
